// Extract inbound SMS payload from Close CRM webhook
const d = $input.first().json.body?.event?.data || {};
if (d.direction !== 'inbound') return [];
const text = String(d.text || '').trim();
if (!text) return [];
return [{ json: { text, remotePhone: d.remote_phone, localPhone: d.local_phone, closeLeadId: d.lead_id, closeContactId: d.contact_id, activityId: d.id } }];

// Parse Claude's JSON output
const reply = $('Build AI Context').item.json;
let parsed = { intent: 'QUESTION', confidence: 0.3, reasoning: 'default fallback' };
try {
  const raw = ($input.first().json.choices?.[0]?.message?.content || '').trim();
  const clean = raw.replace(/^```json\s*/,'').replace(/```\s*$/,'').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  // Fall back to default
}
return [{ json: { ...reply, intent: parsed.intent, classifyConfidence: parsed.confidence, classifyReasoning: parsed.reasoning } }];

// Content filter + validate reply, derive sticky sender from Extract SMS Data.localPhone
const raw = ($input.first().json.choices?.[0]?.message?.content || '').trim();
const FALLBACK = 'hey, thanks for getting back. mind a 15 min call to walk through it? https://calendly.com/client-ai/review-engine-15min';
const BANNED = ['guarantee','free','promise',' bot ','automated','robot','chatbot',' ai '];
let text = raw.replace(/^```(?:text|sms)?\s*/,'').replace(/```\s*$/,'').replace(/^["']|["']$/g,'').trim();
text = text.replace(/[—–]/g,' ').replace(/…/g,'...').replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/\s+/g,' ').trim();
const low = ' ' + text.toLowerCase() + ' ';
let issues = [];
if (!text) issues.push('empty');
if (text.length > 320) issues.push('too_long');
for (const b of BANNED) if (low.indexOf(b) !== -1) issues.push('banned:' + b.trim());
const finalText = issues.length ? FALLBACK : text;

const inbound = $('Extract SMS Data').item.json;
return [{ json: { ...inbound, aiReplyText: finalText, aiValidated: issues.length === 0, validationIssues: issues, replySenderPhone: inbound.localPhone } }];
